  // Return the target index or -1.
}

tasks.solution:
function searchRotated(numbers, target) {
  let left = 0;
  let right = numbers.length - 1;
  while (left <= right) {
    const middle = Math.floor((left + right) / 2);
    if (numbers[middle] === target) return middle;
    if (numbers[left] <= numbers[middle]) {
      if (numbers[left] <= target && target < numbers[middle]) right = middle - 1;
      else left = middle + 1;
    } else if (numbers[middle] < target && target <= numbers[right]) left = middle + 1;
    else right = middle - 1;
  }
  return -1;
}

