tasks.solution:
function decodeString(text) {
  let index = 0;
  const parse = (stop) => {
    const parts = [];
    while (index < text.length && text[index] !== ']') {
      if (/[a-zA-Z]/.test(text[index])) {
        const start = index;
        while (index < text.length && /[a-zA-Z]/.test(text[index])) index += 1;
        parts.push({count: 1, parts: [{literal: text.slice(start, index)}]});
      } else if (/\d/.test(text[index])) {
        const start = index;
        while (index < text.length && /\d/.test(text[index])) index += 1;
        if (text[index] !== '[') return null;
        const count = Number(text.slice(start, index));
        index += 1;
        const inner = parse(true);
        if (inner === null || text[index] !== ']') return null;
        index += 1;
        parts.push({count, parts: inner});
      } else return null;
    }
    return stop || index === text.length ? parts : null;
  };
  const tree = parse(false);
  if (tree === null || index !== text.length) return null;
  const render = (parts) => parts.map((part) => {
    if (part.count === 0) return '';
    const fragment = part.parts.map((child) => child.literal === undefined ? render([child]) : child.literal).join('');
    return fragment.repeat(part.count);
  }).join('');
  try { return render(tree); } catch { return null; }
}

