}

tasks.solution:
function generateParentheses(n) {
  if (n < 0) return [];
  const result = [];
  const path = [];
  const visit = (open, close) => {
    if (path.length === n * 2) { result.push(path.join('')); return; }
    if (open < n) { path.push('('); visit(open + 1, close); path.pop(); }
    if (close < open) { path.push(')'); visit(open, close + 1); path.pop(); }
  };
  visit(0, 0);
  return result;
}

