  // Return whether text can be segmented.
}

tasks.solution:
function canSegment(text, dictionary) {
  const root = {};
  let longest = 0;
  for (const word of dictionary) {
    if (word === '') continue;
    let node = root;
    for (let index = 0; index < word.length; index += 1) { const character = word[index]; node = node[character] || (node[character] = {}); }
    node.end = true;
    longest = Math.max(longest, word.length);
  }
  const reachable = Array(text.length + 1).fill(false);
  reachable[0] = true;
  for (let start = 0; start < text.length; start += 1) {
    if (!reachable[start]) continue;
    let node = root;
    for (let end = start; end < text.length && end < start + longest; end += 1) {
      node = node[text[end]];
      if (!node) break;
      if (node.end) reachable[end + 1] = true;
    }
  }
  return reachable[text.length];
}

