function canFinish(courseCount, prerequisites) {
  if (!Number.isInteger(courseCount) || courseCount < 0) return false;
  const edges = Array.from({length: courseCount}, () => []);
  const indegree = Array(courseCount).fill(0);
  for (const edge of prerequisites) {
    if (!Array.isArray(edge) || edge.length !== 2 || !Number.isInteger(edge[0]) || !Number.isInteger(edge[1]) || edge[0] < 0 || edge[0] >= courseCount || edge[1] < 0 || edge[1] >= courseCount) return false;
    edges[edge[1]].push(edge[0]);
    indegree[edge[0]] += 1;
  }
  const queue = [];
  for (let course = 0; course < courseCount; course += 1) if (indegree[course] === 0) queue.push(course);
  for (let head = 0; head < queue.length; head += 1) for (const next of edges[queue[head]]) if (--indegree[next] === 0) queue.push(next);
  return queue.length === courseCount;
}

