function countIslands(grid) {
  // Return the number of four-direction islands.
}

tasks.solution:
function countIslands(grid) {
  if (grid.length === 0) return 0;
  const width = grid[0].length;
  if (grid.some((row) => row.length !== width || /[^01]/.test(row))) return 0;
  const seen = new Set();
  let islands = 0;
  for (let row = 0; row < grid.length; row += 1) for (let column = 0; column < width; column += 1) {
    const key = row * width + column;
    if (grid[row][column] !== '1' || seen.has(key)) continue;
    islands += 1;
    const queue = [[row, column]];
    seen.add(key);
    for (let head = 0; head < queue.length; head += 1) for (const [nextRow, nextColumn] of [[queue[head][0] - 1, queue[head][1]], [queue[head][0] + 1, queue[head][1]], [queue[head][0], queue[head][1] - 1], [queue[head][0], queue[head][1] + 1]]) {
      const nextKey = nextRow * width + nextColumn;
      if (nextRow >= 0 && nextRow < grid.length && nextColumn >= 0 && nextColumn < width && grid[nextRow][nextColumn] === '1' && !seen.has(nextKey)) { seen.add(nextKey); queue.push([nextRow, nextColumn]); }
    }
  }
  return islands;
}

