tasks.starterCode:
function lruTranscript(capacity, ops) {
  // Return one JSON result for each operation.
}

tasks.solution:
function lruTranscript(capacity, ops) {
  if (!Number.isInteger(capacity) || capacity < 0) return [];
  const nodes = new Map();
  const head = {key: null, value: null};
  const tail = {key: null, value: null};
  head.next = tail; tail.prev = head;
  const remove = (node) => { node.prev.next = node.next; node.next.prev = node.prev; };
  const append = (node) => { node.prev = tail.prev; node.next = tail; tail.prev.next = node; tail.prev = node; };
  const results = [];
  for (const operation of ops) {
    if (operation[0] === 'get') {
      const node = nodes.get(operation[1]);
      if (!node) results.push(-1);
      else { remove(node); append(node); results.push(node.value); }
    } else if (operation[0] === 'put') {
      if (capacity > 0) {
        let node = nodes.get(operation[1]);
        if (node) { node.value = operation[2]; remove(node); }
        else { node = {key: operation[1], value: operation[2]}; nodes.set(node.key, node); }
        append(node);
        if (nodes.size > capacity) { const oldest = head.next; remove(oldest); nodes.delete(oldest.key); }
      }
      results.push(null);
    } else results.push(null);
  }
  return results;
}

